"""Italiano — profeti (prophets_001 … prophets_150)."""

T = {
"prophets_001": ("Quale profeta costruì l'arca per ordine di Allah?", ["Nuh (Noè)", "Ibrahim (Abramo)", "Musa (Mosè)", "Yusuf (Giuseppe)"], "Allah ordinò a Nuh di costruire l'arca per salvare i credenti dal diluvio."),
"prophets_002": ("Quale profeta fu gettato in un fuoco che Allah rese fresco e sicuro per lui?", ["Ibrahim (Abramo)", "Nuh (Noè)", "Dawud (Davide)", "Ayyub (Giobbe)"], "Allah ordinò al fuoco di essere fresco e sicuro per Ibrahim."),
"prophets_003": ("Quale profeta fu inghiottito da un enorme pesce?", ["Yunus (Giona)", "Ilyas (Elia)", "Idris (Enoch)", "Zakariyya (Zaccaria)"], "Yunus fu inghiottito dal pesce dopo aver lasciato il suo popolo in collera; Allah lo perdonò."),
"prophets_004": ("Quale profeta interpretò il sogno del re con sette vacche grasse e sette vacche magre?", ["Yusuf (Giuseppe)", "Ya'qub (Giacobbe)", "Isma'il (Ismaele)", "Ishaq (Isacco)"], "Yusuf interpretò il sogno del re, annunciando sette anni di abbondanza seguiti da sette anni di carestia."),
"prophets_005": ("A quale profeta, secondo il Corano, Allah parlò direttamente?", ["Musa (Mosè)", "Harun (Aronne)", "Yusuf (Giuseppe)", "Sulaiman (Salomone)"], "Il Corano afferma che Allah parlò a Musa direttamente."),
"prophets_006": ("Quale profeta comprendeva il linguaggio degli uccelli?", ["Sulaiman (Salomone)", "Dawud (Davide)", "Yunus (Giona)", "Yusuf (Giuseppe)"], "Allah insegnò a Sulaiman il linguaggio degli uccelli."),
"prophets_007": ("A quale profeta fu data la scrittura chiamata Zabur (Salmi)?", ["Dawud (Davide)", "Musa (Mosè)", "Isa (Gesù)", "Ibrahim (Abramo)"], "Il Corano menziona che lo Zabur fu dato a Dawud."),
"prophets_008": ("Quale profeta nacque senza padre, per la parola di Allah «Sii, ed è»?", ["Isa (Gesù)", "Yahya (Giovanni)", "Isma'il (Ismaele)", "Ishaq (Isacco)"], "Il Corano descrive la nascita miracolosa di Isa senza padre, per la sola parola di Allah."),
"prophets_009": ("Quale capitolo (sura) del Corano porta il nome della madre di un profeta?", ["Maryam", "Yusuf", "Nuh", "Hud"], "La sura 19, Maryam, prende il nome dalla madre del profeta Isa."),
"prophets_010": ("Quale profeta fu messo alla prova con una grave malattia ed è lodato per la sua pazienza?", ["Ayyub (Giobbe)", "Zakariyya (Zaccaria)", "Yahya (Giovanni)", "Idris (Enoch)"], "Ayyub restò paziente durante una prova durissima, e Allah lo ricompensò."),
"prophets_011": ("Davanti a chi Allah ordinò agli angeli di prostrarsi, in segno di onore?", ["Adam", "Nuh (Noè)", "Ibrahim (Abramo)", "Musa (Mosè)"], "Allah ordinò agli angeli di prostrarsi davanti ad Adam in segno di onore, non di adorazione."),
"prophets_012": ("Quale profeta è chiamato «Khalilullah», l'amico intimo di Allah?", ["Ibrahim (Abramo)", "Musa (Mosè)", "Isa (Gesù)", "Muhammad ﷺ"], "Il Corano descrive Ibrahim come l'amico intimo (khalil) di Allah."),
"prophets_013": ("Quale profeta fu gettato in un pozzo dai suoi fratelli?", ["Yusuf (Giuseppe)", "Bunyamin (Beniamino)", "Ya'qub (Giacobbe)", "Isma'il (Ismaele)"], "I fratelli di Yusuf lo gettarono in un pozzo per gelosia."),
"prophets_014": ("Il popolo di quale profeta fu distrutto da un diluvio dopo averlo respinto?", ["Nuh (Noè)", "Hud", "Salih", "Shu'ayb"], "Il popolo di Nuh fu travolto dal diluvio dopo aver ostinatamente respinto il suo messaggio."),
"prophets_015": ("Quale profeta vide il mare aprirsi per salvare il suo popolo dal Faraone?", ["Musa (Mosè)", "Harun (Aronne)", "Yusuf (Giuseppe)", "Isma'il (Ismaele)"], "Allah ordinò a Musa di colpire il mare, che si aprì perché i credenti potessero passare."),
"prophets_016": ("Quale profeta, insieme al padre Dawud, giudicò il caso di un campo brucato dalle pecore?", ["Sulaiman (Salomone)", "Isma'il (Ismaele)", "Yusuf (Giuseppe)", "Ishaq (Isacco)"], "Il Corano racconta che Sulaiman e Dawud giudicarono questo caso, e Allah ne diede la comprensione a Sulaiman."),
"prophets_017": ("A quale madre fu ordinato di mettere il suo bambino in un fiume?", ["Musa (Mosè)", "Isa (Gesù)", "Yusuf (Giuseppe)", "Isma'il (Ismaele)"], "Allah ispirò la madre di Musa a metterlo in una cesta sul fiume per proteggerlo."),
"prophets_018": ("La cammella di quale profeta fu un segno dato al suo popolo, i Thamud?", ["Salih", "Hud", "Shu'ayb", "Lut (Lot)"], "Allah inviò una cammella come segno al popolo dei Thamud tramite il profeta Salih."),
"prophets_019": ("A quale profeta Allah insegnò i nomi di tutte le cose?", ["Adam", "Nuh (Noè)", "Ibrahim (Abramo)", "Musa (Mosè)"], "Allah insegnò ad Adam i nomi di tutte le cose, e gli angeli riconobbero la sapienza di Allah."),
"prophets_020": ("Quale profeta parlò alla gente quando era ancora un neonato nella culla?", ["Isa (Gesù)", "Yahya (Giovanni)", "Yusuf (Giuseppe)", "Ismail (Ismaele)"], "Il piccolo Isa parlò dalla culla: «Io sono il servo di Allah; Egli mi ha dato la Scrittura.»"),
"prophets_021": ("Con quale figlio Ibrahim innalzò le fondamenta della Ka'ba?", ["Ismail (Ismaele)", "Ishaq (Isacco)", "Yaqub (Giacobbe)", "Yusuf (Giuseppe)"], "«E quando Ibrahim e Ismail innalzavano le fondamenta della Casa…»: la costruirono insieme."),
"prophets_022": ("Quale figlio fu annunciato al profeta Zakariyya nella sua vecchiaia?", ["Yahya (Giovanni)", "Isa (Gesù)", "Ismail (Ismaele)", "Ishaq (Isacco)"], "«O Zakariyya, ti annunciamo la buona novella di un bambino il cui nome sarà Yahya.»"),
"prophets_023": ("In che cosa si trasformò il bastone di Musa quando Allah gli disse di gettarlo?", ["In un serpente che si muoveva", "In un uccello", "In una sorgente d'acqua", "In una luce"], "«Gettalo, o Musa!» Lo gettò, ed ecco che divenne un serpente che si muoveva rapidamente."),
"prophets_024": ("Nel suo sogno, che cosa vide il giovane Yusuf prostrarsi davanti a lui?", ["Undici stelle, il sole e la luna", "Sette vacche grasse", "Una pioggia d'oro", "Un giardino di palme"], "Yusuf vide undici stelle, il sole e la luna prostrarsi davanti a lui: un segno del suo destino."),
"prophets_025": ("A quale popolo fu inviato il profeta Hud?", ["Gli 'Ad", "I Thamud", "Il popolo di Madyan", "Il popolo del Faraone"], "«E agli 'Ad, il loro fratello Hud…»: li chiamò ad adorare Allah soltanto."),
"prophets_026": ("A quale popolo fu inviato il profeta Shu'ayb?", ["Il popolo di Madyan", "Gli 'Ad", "I Thamud", "Il popolo di Nuh"], "«E a Madyan, il loro fratello Shu'ayb…»: ordinò loro di dare misura e peso giusti."),
"prophets_027": ("Quale profeta è chiamato «Dhun-Nun» (l'uomo del pesce) nel Corano?", ["Yunus (Giona)", "Musa (Mosè)", "Sulayman (Salomone)", "Ayyub (Giobbe)"], "«E Dhun-Nun, quando se ne andò in collera…»: è Yunus, poi inghiottito dal pesce."),
"prophets_028": ("In quale sura Musa viaggia per imparare da un servo a cui Allah diede una conoscenza speciale?", ["Al-Kahf (La Caverna)", "Yusuf", "Maryam", "An-Naml"], "Nella sura Al-Kahf, Musa accompagna un servo sapiente e impara la pazienza davanti a ciò che ancora non comprende."),
"prophets_029": ("Quale profeta è menzionato per nome più spesso nel Corano?", ["Musa (Mosè)", "Ibrahim (Abramo)", "Nuh (Noè)", "Isa (Gesù)"], "Musa è il profeta nominato più di frequente nel Corano; la sua storia con il Faraone ritorna molte volte."),
"prophets_030": ("Quanti profeti sono menzionati per nome nel Corano?", ["25", "10", "50", "99"], "Venticinque profeti sono nominati nel Corano, da Adam a Muhammad ﷺ."),
"prophets_031": ("Con il permesso di Allah, quale profeta guarì il cieco e il lebbroso?", ["Isa (Gesù)", "Musa (Mosè)", "Dawud (Davide)", "Yunus (Giona)"], "Isa guarì il cieco e il lebbroso con il permesso di Allah: un segno per il suo popolo."),
"prophets_032": ("Secondo il Corano, per quanto tempo Nuh rimase tra il suo popolo chiamandolo ad Allah?", ["950 anni", "100 anni", "300 anni", "40 anni"], "«Rimase tra loro mille anni meno cinquanta»: 950 anni di paziente richiamo."),
"prophets_033": ("Secondo il Corano, da che cosa Allah creò Adam?", ["Dall'argilla", "Dalla luce", "Dal fuoco", "Dall'acqua"], "Allah disse agli angeli: «Creerò un essere umano dall'argilla.»"),
"prophets_034": ("Chi tentò Adam e sua moglie a mangiare dall'albero proibito?", ["Shaytan (Iblis)", "Un angelo", "Un uccello", "Un re"], "Shaytan sussurrò loro perché mangiassero dall'albero che Allah aveva proibito."),
"prophets_035": ("Quale motivo diede Iblis per rifiutarsi di prostrarsi davanti ad Adam?", ["«Io sono migliore di lui: mi hai creato dal fuoco e lui dall'argilla»", "Non sapeva chi fosse Adam", "Aveva paura degli angeli", "Dormiva"], "Iblis rifiutò per orgoglio: «Mi hai creato dal fuoco, e lui lo hai creato dall'argilla.»"),
"prophets_036": ("Dopo l'uccisione tra i due figli di Adam, quale animale Allah inviò per mostrare come seppellire il corpo?", ["Un corvo", "Un cane", "Una colomba", "Una volpe"], "Allah inviò un corvo che raspò la terra per mostrare all'assassino come nascondere il corpo del fratello."),
"prophets_037": ("Che cosa dice il Corano del profeta Idris?", ["Allah lo elevò a un alto rango", "Costruì un'arca", "Fu inghiottito da un pesce", "Parlò alle formiche"], "«E lo elevammo a un alto rango.»"),
"prophets_038": ("Che cosa fece il figlio di Nuh quando il padre lo chiamò nell'arca?", ["Rifiutò e disse che si sarebbe rifugiato su una montagna", "Salì per primo", "Costruì la propria arca", "Andò a radunare gli animali"], "Disse: «Mi rifugerò su una montagna»; le onde lo travolsero."),
"prophets_039": ("Su quale monte si posò l'arca di Nuh, secondo il Corano?", ["Il monte Judi", "Il monte Sinai", "Il monte Uhud", "Il monte Arafat"], "«E l'arca si posò sul Judi.»"),
"prophets_040": ("Che cosa Allah ordinò a Nuh di caricare nell'arca?", ["Una coppia di ogni specie, e i credenti", "Solo la sua famiglia", "Solo uccelli", "Oro e argento"], "«Caricavi una coppia di ogni specie, e la tua famiglia… e chi ha creduto.»"),
"prophets_041": ("Che cosa fecero i notabili del popolo di Nuh quando lo videro costruire l'arca?", ["Lo derisero", "Lo aiutarono", "Gli portarono legna", "Pregarono con lui"], "Ogni volta che i notabili del suo popolo passavano, lo deridevano."),
"prophets_042": ("Come descrive il Corano Nuh nella sura Al-Isra?", ["Un servo riconoscente", "Un re potente", "Un grande viaggiatore", "Un uomo silenzioso"], "«In verità, era un servo riconoscente.»"),
"prophets_043": ("Come furono distrutti gli 'Ad, ai quali fu inviato Hud?", ["Da un vento violento e furioso", "Da un diluvio", "Da una pioggia di pietre", "Da un terremoto"], "«Quanto agli 'Ad, furono distrutti da un vento urlante e violento.»"),
"prophets_044": ("Che cosa colpì i Thamud, il popolo di Salih?", ["Un grido terribile", "Un diluvio", "Una carestia", "Uno sciame di cavallette"], "«E il grido colpì coloro che erano stati ingiusti.»"),
"prophets_045": ("Qual è il nome del padre di Ibrahim menzionato nel Corano?", ["Azar", "Tarih", "Lut", "Kan'an"], "«Ibrahim disse a suo padre Azar: prendi degli idoli come divinità?»"),
"prophets_046": ("Dopo aver distrutto gli idoli, quale lasciò intatto Ibrahim?", ["Il più grande", "Il più piccolo", "Quello d'oro", "Nessuno, li distrusse tutti"], "Li ridusse in pezzi, tranne il più grande, perché il suo popolo lo interrogasse."),
"prophets_047": ("Dopo aver visto tramontare la stella, la luna e poi il sole, che cosa dichiarò Ibrahim?", ["«Non amo ciò che tramonta»", "«Il sole è il mio signore»", "«La luna è la più bella»", "«Dormirò»"], "Quando ciascuno tramontava diceva: «Non amo ciò che tramonta», poi si rivolse al Creatore."),
"prophets_048": ("Quanti uccelli Allah disse a Ibrahim di prendere, per mostrargli come ridà vita ai morti?", ["Quattro", "Due", "Sette", "Dodici"], "«Prendi quattro uccelli… poi chiamali: verranno a te in fretta.»"),
"prophets_049": ("Che cosa servì Ibrahim ai suoi ospiti, gli angeli venuti con la buona novella?", ["Un vitello arrostito", "Datteri", "Latte", "Pane e miele"], "«Non tardò a portare un vitello arrostito.»"),
"prophets_050": ("Quale buona novella portarono gli angeli alla moglie di Ibrahim?", ["La nascita di Ishaq", "Un viaggio", "Una grande ricchezza", "Una pioggia abbondante"], "«Le demmo la buona novella di Ishaq, e dopo Ishaq, di Ya'qub.»"),
"prophets_051": ("Come reagì il figlio di Ibrahim quando il padre gli raccontò il sogno di sacrificarlo?", ["Accettò: «Fa' ciò che ti è ordinato»", "Scappò", "Pianse e rifiutò", "Si nascose"], "Disse: «Padre mio, fa' ciò che ti è ordinato.» E Allah lo riscattò con un grande sacrificio."),
"prophets_052": ("Nella sua preghiera, dove dice Ibrahim di aver stabilito parte della sua famiglia?", ["In una valle senza coltivazioni, presso la Casa Sacra", "Sulle rive del Nilo", "In una foresta", "Su un'isola"], "«Ho stabilito parte della mia discendenza in una valle incolta presso la Tua Casa Sacra.»"),
"prophets_053": ("Che cosa chiese Ibrahim per la città della Mecca nella sua preghiera?", ["Che fosse una città sicura e che i suoi abitanti ricevessero frutti", "Che diventasse un regno", "Che vi piovesse sempre", "Che avesse un fiume"], "«Signore mio, fa' di questa una città sicura e provvedi ai suoi abitanti con frutti.»"),
"prophets_054": ("Innalzando la Ka'ba, Ibrahim e Isma'il chiesero ad Allah di inviare tra i loro discendenti…?", ["Un messaggero tra di loro, che recitasse i Suoi versetti", "Un re", "Un esercito", "Un tesoro"], "«Signore nostro, invia tra loro un messaggero dei loro, che reciti loro i Tuoi versetti.»"),
"prophets_055": ("Il Corano dice che un profeta fu, da solo, «una nazione (umma)». Quale?", ["Ibrahim", "Nuh", "Musa", "Sulayman"], "«In verità, Ibrahim era una nazione, devotamente obbediente ad Allah, retto.»"),
"prophets_056": ("Per quale qualità il Corano loda Isma'il nella sura Maryam?", ["Era fedele alla sua promessa", "Era molto ricco", "Era un re", "Sapeva nuotare"], "«In verità, era fedele alla sua promessa, ed era un messaggero e un profeta.»"),
"prophets_057": ("Quale castigo colpì il popolo di Lut?", ["Una pioggia di pietre d'argilla cotta", "Un diluvio", "Uno sciame di insetti", "Una siccità"], "«Capovolgemmo la città e facemmo piovere su di essa pietre d'argilla cotta.»"),
"prophets_058": ("Le mogli di quali due profeti il Corano presenta come esempio di miscredenza?", ["Nuh e Lut", "Ibrahim e Musa", "Dawud e Sulayman", "Ayyub e Yunus"], "«Allah propone come esempio ai miscredenti la moglie di Nuh e la moglie di Lut.»"),
"prophets_059": ("Chi era il padre di Ya'qub?", ["Ishaq", "Isma'il", "Ibrahim", "Yusuf"], "Gli angeli annunciarono alla moglie di Ibrahim «Ishaq, e dopo Ishaq, Ya'qub»."),
"prophets_060": ("Che cosa accadde alla vista di Ya'qub a forza di piangere per Yusuf?", ["I suoi occhi divennero bianchi", "Vedeva meglio di notte", "Nulla cambiò", "Perse un occhio"], "«I suoi occhi divennero bianchi per il dolore, ed egli lo tratteneva.»"),
"prophets_061": ("Che cosa restituì la vista a Ya'qub?", ["La camicia di Yusuf gettata sul suo viso", "Una pianta", "L'acqua di Zamzam", "Un unguento"], "Yusuf disse: «Gettate la mia camicia sul viso di mio padre; recupererà la vista.»"),
"prophets_062": ("Che cosa preferì Yusuf piuttosto che cedere a ciò a cui veniva ingiustamente invitato?", ["La prigione", "L'esilio", "La ricchezza", "Il silenzio"], "«Signore mio, la prigione mi è più cara di ciò a cui mi invitano.»"),
"prophets_063": ("In prigione, due giovani raccontarono a Yusuf i loro sogni. Che cosa vide uno di loro?", ["Spremeva dell'uva", "Volava", "Pascolava pecore", "Scavava un pozzo"], "Uno si vide spremere del vino, l'altro portare sulla testa del pane che gli uccelli mangiavano."),
"prophets_064": ("Quanti anni di abbondanza e poi di siccità predisse Yusuf al re?", ["Sette e sette", "Tre e tre", "Dieci e dieci", "Uno e uno"], "«Seminerete per sette anni… poi verranno sette anni difficili.»"),
"prophets_065": ("Quale incarico chiese Yusuf al re d'Egitto?", ["I depositi del paese", "Il comando dell'esercito", "Il trono", "Il tesoro d'oro"], "«Affidami i depositi del paese: sono un custode sapiente.»"),
"prophets_066": ("Che cosa fece mettere Yusuf nel bagaglio del fratello minore per tenerlo accanto a sé?", ["La coppa del re", "Un sacco d'oro", "Una lettera", "La sua camicia"], "«Mise la coppa nel sacco di suo fratello.»"),
"prophets_067": ("Quale consiglio diede Ya'qub ai suoi figli prima che entrassero in Egitto?", ["Entrare da porte diverse", "Viaggiare di notte", "Travestirsi", "Portare doni"], "«Non entrate da una sola porta, ma entrate da porte diverse.»"),
"prophets_068": ("Perché i fratelli di Yusuf vennero in Egitto quando lui ne era responsabile?", ["Per procurarsi provviste durante la carestia", "Per ritrovarlo", "Per un pellegrinaggio", "Per vendere cammelli"], "I suoi fratelli vennero per il grano; entrarono da lui e non lo riconobbero."),
"prophets_069": ("In quale casa fu accolto il piccolo Musa dopo essere stato messo nel fiume?", ["Quella del Faraone", "Quella di un pastore", "Quella di un pescatore", "Quella di un mercante"], "La famiglia del Faraone lo raccolse, perché un giorno fosse per loro un nemico e un motivo di afflizione."),
"prophets_070": ("Come tornò infine il piccolo Musa da sua madre?", ["Rifiutò ogni nutrice, e sua sorella suggerì sua madre", "Il Faraone lo restituì per pietà", "Sua madre lo rubò di notte", "Un angelo lo portò"], "Allah gli fece rifiutare le nutrici; sua sorella suggerì una famiglia: era sua madre, che lo allattò."),
"prophets_071": ("Perché Musa dovette lasciare l'Egitto in fretta, prima della sua missione?", ["Aveva ucciso un uomo involontariamente con un colpo", "Aveva rubato dal palazzo", "Rifiutava di pagare le tasse", "Aveva insultato il Faraone"], "Colpì un egiziano che lottava con un uomo del suo popolo e lo uccise; se ne pentì subito."),
"prophets_072": ("Chi avvertì Musa che i notabili complottavano per ucciderlo?", ["Un uomo venuto di corsa dall'altro capo della città", "Sua madre", "Harun", "Un soldato"], "«Un uomo venne di corsa dall'estremità della città: complottano per ucciderti, parti!»"),
"prophets_073": ("Arrivato a Madyan, che cosa fece Musa per due donne all'abbeveratoio?", ["Abbeverò il loro gregge", "Vendette loro un cammello", "Costruì loro una casa", "Insegnò loro a leggere"], "Abbeverò il loro gregge, poi si ritirò all'ombra invocando Allah."),
"prophets_074": ("Quanti anni l'anziano di Madyan chiese a Musa di lavorare per sposare sua figlia?", ["Otto, e dieci se voleva", "Uno", "Quaranta", "Tre"], "«Mi servirai per otto anni; se ne completerai dieci, sarà per tua scelta.»"),
"prophets_075": ("Che cosa Allah ordinò a Musa di togliere nella valle sacra di Tuwa?", ["I sandali", "Il mantello", "Il bastone", "Il turbante"], "«Togliti i sandali: sei nella valle sacra di Tuwa.»"),
"prophets_076": ("Quale fu il secondo segno dato a Musa, dopo il bastone?", ["La sua mano uscì bianca, senza alcun male", "Poteva volare", "La sua voce divenne tuono", "Vedeva di notte"], "«Stringi la mano al fianco: uscirà bianca, senza alcun male.»"),
"prophets_077": ("Che cosa chiese Musa ad Allah prima di andare dal Faraone?", ["Di aprirgli il petto e sciogliergli la lingua", "Un esercito", "Oro", "Un cavallo veloce"], "«Signore mio, aprimi il petto, facilita il mio compito e sciogli il nodo della mia lingua.»"),
"prophets_078": ("Chi chiese Musa ad Allah come aiutante nella sua missione?", ["Suo fratello Harun", "Suo figlio", "Suo suocero", "Un angelo"], "«Dammi un aiutante della mia famiglia: Harun, mio fratello.»"),
"prophets_079": ("Che cosa fecero i maghi del Faraone quando il bastone di Musa inghiottì le loro illusioni?", ["Caddero in prostrazione e credettero", "Fuggirono", "Risero", "Attaccarono Musa"], "I maghi caddero in prostrazione: «Crediamo nel Signore dei mondi, il Signore di Musa e Harun.»"),
"prophets_080": ("Quale di queste piaghe il Corano elenca tra quelle inviate contro il popolo del Faraone?", ["Le cavallette", "La neve", "I lupi", "Il fuoco"], "«Inviammo contro di loro l'inondazione, le cavallette, i pidocchi, le rane e il sangue.»"),
"prophets_081": ("Secondo il Corano, che cosa fece Allah del corpo del Faraone dopo che annegò?", ["Lo preservò come segno", "Lo fece sparire", "Lo bruciò", "Lo restituì al suo popolo"], "«Oggi salveremo il tuo corpo, perché tu sia un segno per coloro che verranno dopo di te.»"),
"prophets_082": ("Secondo il Corano, che cosa chiese ad Allah la moglie credente del Faraone?", ["Una casa presso di Lui in Paradiso", "Un figlio", "La morte del Faraone", "Un regno"], "«Signore mio, costruiscimi presso di Te una casa in Paradiso, e salvami dal Faraone.»"),
"prophets_083": ("Quante notti durò l'appuntamento di Allah con Musa sul monte?", ["Quaranta", "Sette", "Dieci", "Cento"], "«Fissammo a Musa trenta notti e le completammo con dieci: quaranta notti.»"),
"prophets_084": ("Che cosa accadde quando Musa chiese di vedere Allah?", ["Allah si manifestò al monte, che si sgretolò, e Musa cadde svenuto", "Vide Allah", "Non accadde nulla", "Il monte si sollevò nel cielo"], "«Guarda il monte: se resta al suo posto, Mi vedrai.» Il monte fu polverizzato e Musa cadde svenuto."),
"prophets_085": ("Su che cosa Allah scrisse esortazioni e spiegazioni per Musa?", ["Sulle Tavole", "Su foglie di palma", "Su una pietra nera", "Sul cuoio"], "«Scrivemmo per lui sulle Tavole un'esortazione su ogni cosa.»"),
"prophets_086": ("Chi fabbricò il vitello che i Figli d'Israele adorarono mentre Musa era assente?", ["As-Samiri", "Harun", "Il Faraone", "Qarun"], "«As-Samiri li ha sviati»: dai loro ornamenti produsse un vitello che emetteva un muggito."),
"prophets_087": ("Quante sorgenti sgorgarono dalla roccia che Musa colpì con il bastone?", ["Dodici", "Sette", "Tre", "Quaranta"], "«Colpisci la roccia con il tuo bastone»: sgorgarono dodici sorgenti, una per ogni tribù."),
"prophets_088": ("Quale cibo Allah fece scendere per i Figli d'Israele nel deserto?", ["La manna e le quaglie", "Riso e pesce", "Datteri e latte", "Pane e olive"], "«Facemmo scendere su di voi la manna e le quaglie.»"),
"prophets_089": ("Di che colore era la vacca che Musa disse ai Figli d'Israele di sacrificare?", ["Giallo brillante", "Nera", "Bianca", "Rossa"], "«È una vacca gialla, di colore vivo, che rallegra chi la guarda.»"),
"prophets_090": ("Chi, tra il popolo di Musa, fu inghiottito dalla terra con la sua casa per la sua arroganza e ricchezza?", ["Qarun", "Haman", "As-Samiri", "Jalut"], "Qarun possedeva immensi tesori; «facemmo inghiottire lui e la sua casa dalla terra»."),
"prophets_091": ("Quale metallo Allah rese malleabile per Dawud?", ["Il ferro", "L'oro", "Il rame", "L'argento"], "«E rendemmo malleabile il ferro per lui.»"),
"prophets_092": ("Che cosa Allah insegnò a Dawud a fabbricare, per proteggere le persone in battaglia?", ["Cotte di maglia", "Spade", "Scudi di legno", "Torri"], "«Gli insegnammo a fabbricare corazze per proteggervi.»"),
"prophets_093": ("Quale gigante uccise Dawud in battaglia, secondo il Corano?", ["Jalut (Golia)", "Il Faraone", "Haman", "Nimrod"], "«E Dawud uccise Jalut, e Allah gli diede il regno e la saggezza.»"),
"prophets_094": ("Come mise alla prova il re Talut il suo esercito prima di affrontare Jalut?", ["Un fiume: non bere, tranne una manciata", "Una corsa", "Un digiuno di tre giorni", "Una montagna da scalare"], "«Allah vi metterà alla prova con un fiume: chi ne beve non è dei miei, tranne chi ne prende una manciata.»"),
"prophets_095": ("Che cosa Allah fece glorificarLo insieme a Dawud?", ["Le montagne e gli uccelli", "I venti", "I jinn", "I pesci"], "«E sottomettemmo le montagne a glorificarCi con Dawud, e gli uccelli.»"),
"prophets_096": ("Quale elemento Allah sottomise a Sulayman per portarlo dove volesse?", ["Il vento", "Il fuoco", "La pioggia", "Il mare"], "«E a Sulayman, il vento, che soffiava impetuoso al suo comando verso la terra benedetta.»"),
"prophets_097": ("Quale uccello portò a Sulayman notizie del regno di Saba?", ["L'upupa", "L'aquila", "La colomba", "Il corvo"], "L'upupa tornò e disse: «Ho appreso qualcosa che tu non sai, e ti porto da Saba una notizia certa.»"),
"prophets_098": ("Quale piccola creatura avvertì le sue simili di rientrare mentre l'esercito di Sulayman si avvicinava?", ["Una formica", "Un'ape", "Un topo", "Un ragno"], "Una formica disse: «O formiche, entrate nelle vostre dimore, perché Sulayman e i suoi soldati non vi schiaccino senza accorgersene.»"),
"prophets_099": ("In quanto tempo il trono della regina di Saba fu portato a Sulayman?", ["Prima che il suo sguardo tornasse a lui", "In un giorno", "In sette giorni", "In un mese"], "Colui che aveva conoscenza del Libro disse: «Te lo porterò prima che il tuo sguardo torni a te.»"),
"prophets_100": ("Secondo il Corano, che cosa fabbricarono i jinn per Sulayman?", ["Santuari, statue e grandi bacini", "Tappeti volanti", "Navi", "Montagne"], "«Facevano per lui ciò che voleva: santuari, statue, bacini grandi come cisterne e calderoni fissi.»"),
"prophets_101": ("Come vennero a sapere i jinn della morte di Sulayman?", ["Una creatura della terra rosicchiò il suo bastone ed egli cadde", "Un angelo glielo disse", "L'upupa glielo disse", "Lo videro morire"], "Solo la «creatura della terra» che rodeva il suo bastone rivelò la sua morte; i jinn capirono di non conoscere l'invisibile."),
"prophets_102": ("Quale preghiera particolare rivolse Sulayman ad Allah?", ["Un regno che nessuno dopo di lui avrebbe avuto", "Una lunga vita", "La ricchezza di Qarun", "Il potere di volare"], "«Signore mio, perdonami e concedimi un regno che non appartenga a nessuno dopo di me.»"),
"prophets_103": ("Che cosa Allah ordinò ad Ayyub di fare per recuperare la salute?", ["Battere il piede a terra: sgorgò una sorgente fresca", "Digiunare un mese", "Bagnarsi nel mare", "Scalare una montagna"], "«Batti con il piede: ecco una sorgente fresca per lavarti, e da bere.»"),
"prophets_104": ("Quale invocazione fece Yunus nelle tenebre del ventre del pesce?", ["«Non c'è dio all'infuori di Te! Gloria a Te, sono stato tra gli ingiusti»", "«Signore mio, dammi un regno»", "«Signore mio, mandami la pioggia»", "«Signore mio, fammi vederTi»"], "«Gridò nelle tenebre: non c'è divinità all'infuori di Te! Gloria a Te, sono stato tra gli ingiusti.»"),
"prophets_105": ("Quale pianta Allah fece crescere sopra Yunus dopo che il pesce lo ebbe gettato fuori?", ["Una pianta di zucca (yaqtin)", "Una palma", "Un ulivo", "Una vite"], "«E facemmo crescere su di lui una pianta di zucca.»"),
"prophets_106": ("A quante persone fu inviato Yunus, secondo il Corano?", ["Centomila, o più", "Mille", "Diecimila", "Dodici"], "«E lo inviammo a centomila, o più.»"),
"prophets_107": ("Quale segno diede Allah a Zakariyya per confermare la venuta di suo figlio?", ["Non parlare alla gente per tre notti, pur essendo sano", "Una stella cadente", "Pioggia d'estate", "Un sogno"], "«Il tuo segno è che non parlerai alla gente per tre notti, pur essendo sano.»"),
"prophets_108": ("Che cosa dice Allah del nome Yahya?", ["Nessuno prima di lui aveva ricevuto quel nome", "Era il nome di suo nonno", "Lo scelse sua madre", "Era il nome di un re"], "«Ti annunciamo un bambino il cui nome sarà Yahya; non abbiamo dato questo nome a nessuno prima.»"),
"prophets_109": ("Che cosa concesse Allah a Yahya quando era ancora un bambino?", ["La saggezza", "Un regno", "Un cavallo", "Un tesoro"], "«O Yahya, prendi la Scrittura con fermezza.» E gli demmo il giudizio quando era ancora un bambino."),
"prophets_110": ("Che cosa aveva promesso in voto la madre di Maryam per il bambino che portava in grembo?", ["Di consacrarlo al servizio di Allah", "Di mandarlo in Egitto", "Di farne un re", "Di affidarlo a un pastore"], "«Signore mio, Ti ho consacrato in voto ciò che è nel mio grembo, dedicato al Tuo servizio.»"),
"prophets_111": ("Quale profeta si prese cura di Maryam dopo la sua nascita?", ["Zakariyya", "Yahya", "Isa", "Dawud"], "«E la affidò alle cure di Zakariyya», che trovava presso di lei provviste da Allah."),
"prophets_112": ("Secondo il Corano, Allah scelse Maryam al di sopra di chi?", ["Le donne dei mondi", "Le regine", "Gli angeli", "I profeti"], "«O Maryam, Allah ti ha scelta e purificata, e ti ha scelta al di sopra delle donne dei mondi.»"),
"prophets_113": ("Che cosa cadde per Maryam quando scosse il tronco della palma?", ["Datteri freschi e maturi", "Olive", "Fichi", "Pioggia"], "«Scuoti verso di te il tronco della palma: farà cadere su di te datteri freschi e maturi.»"),
"prophets_114": ("Quale parola usa il Corano per Maryam nella sura Al-Ma'ida?", ["Veritiera (siddiqa)", "Regina", "Profetessa", "Guerriera"], "«Il Messia, figlio di Maryam, non era che un messaggero… e sua madre era una veritiera.»"),
"prophets_115": ("Quale titolo dà il Corano a Isa, figlio di Maryam?", ["Al-Masih (il Messia)", "Al-Khalil", "Al-Kalim", "As-Siddiq"], "«Il suo nome sarà il Messia, Isa figlio di Maryam, illustre in questo mondo e nell'Altro.»"),
"prophets_116": ("Che cosa modellò Isa dall'argilla, con il permesso di Allah?", ["La forma di un uccello, che prese vita", "Una casa", "La statua di un re", "Una barca"], "«Modello per voi dall'argilla la forma di un uccello, poi vi soffio dentro e diventa un uccello con il permesso di Allah.»"),
"prophets_117": ("Come si chiamano i compagni intimi di Isa, che si dichiararono «aiutanti di Allah»?", ["Gli Hawariyyun (i discepoli)", "Gli Ansar", "I Muhajirun", "I Sahaba"], "«I discepoli dissero: noi siamo gli aiutanti di Allah.»"),
"prophets_118": ("Che cosa chiesero i discepoli a Isa, che diede il nome alla sura Al-Ma'ida?", ["Una tavola imbandita fatta scendere dal cielo", "Un libro", "Un regno", "Oro"], "«Può il tuo Signore far scendere su di noi una tavola imbandita dal cielo?»"),
"prophets_119": ("Che cosa dice il Corano sulla fine della missione di Isa sulla terra?", ["Non fu né ucciso né crocifisso: Allah lo elevò a Sé", "Morì di vecchiaia", "Annegò", "Andò in Egitto"], "«Non lo uccisero, né lo crocifissero… piuttosto, Allah lo elevò a Sé.»"),
"prophets_120": ("Con quale nome Isa annunciò un messaggero che sarebbe venuto dopo di lui?", ["Ahmad", "Yahya", "Musa", "Ilyas"], "«…annunciando la buona novella di un messaggero che verrà dopo di me, il cui nome è Ahmad.»"),
"prophets_121": ("Per l'adorazione di quale idolo il profeta Ilyas rimproverò il suo popolo?", ["Ba'l", "Hubal", "Al-Lat", "Wadd"], "«Invocate Ba'l e abbandonate il migliore dei creatori?»"),
"prophets_122": ("Quali tre profeti il Corano menziona insieme «tra i pazienti»?", ["Isma'il, Idris e Dhul-Kifl", "Nuh, Hud e Salih", "Musa, Harun e Yusha'", "Dawud, Sulayman e Ayyub"], "«E Isma'il, Idris e Dhul-Kifl: tutti erano tra i pazienti.»"),
"prophets_123": ("Quale profeta è nominato nella sura Sad accanto a Isma'il e Dhul-Kifl?", ["Al-Yasa' (Eliseo)", "Yunus", "Lut", "Shu'ayb"], "«E ricorda Isma'il, Al-Yasa' e Dhul-Kifl: tutti sono tra i migliori.»"),
"prophets_124": ("Quale titolo dà il Corano al Profeta Muhammad ﷺ nel versetto 33:40?", ["Il Sigillo dei Profeti", "Il Re degli Arabi", "Il Padre dei credenti", "L'Amico di Allah"], "«Muhammad… è il Messaggero di Allah e il Sigillo dei Profeti.»"),
"prophets_125": ("Secondo il Corano, come che cosa fu inviato il Profeta Muhammad ﷺ?", ["Una misericordia per i mondi", "Un re", "Un giudice", "Un guerriero"], "«Non ti abbiamo inviato se non come misericordia per i mondi.»"),
"prophets_126": ("Secondo il versetto 33:56, che cosa fanno Allah e i Suoi angeli per il Profeta ﷺ?", ["Inviano benedizioni su di lui", "Lo proteggono dai venti", "Gli mandano la pioggia", "Lo osservano in silenzio"], "«Allah e i Suoi angeli inviano benedizioni sul Profeta. O credenti, invocate benedizioni su di lui e salutatelo con la pace.»"),
"prophets_127": ("Come descrive il Corano il carattere del Profeta ﷺ nella sura Al-Qalam?", ["«Tu sei di un carattere sublime»", "«Tu sei un grande re»", "«Tu sei il più ricco»", "«Tu sei il più forte»"], "«E in verità, tu sei di un carattere sublime.»"),
"prophets_128": ("Che cosa ci ricorda il versetto 3:144 riguardo a Muhammad ﷺ?", ["È solo un messaggero, e altri messaggeri sono passati prima di lui", "Non morirà mai", "È un angelo", "Conosce il futuro"], "«Muhammad non è che un messaggero; altri messaggeri sono passati prima di lui.»"),
"prophets_129": ("Quali cinque profeti nomina insieme il versetto 33:7 per il patto solenne?", ["Nuh, Ibrahim, Musa, Isa e Muhammad ﷺ", "Adam, Nuh, Hud, Salih e Lut", "Dawud, Sulayman, Ayyub, Yunus e Idris", "Isma'il, Ishaq, Ya'qub, Yusuf e Musa"], "«Prendemmo dai profeti il loro patto: da te, da Nuh, Ibrahim, Musa e Isa figlio di Maryam.»"),
"prophets_130": ("Secondo un hadith in al-Bukhari, quale mestiere svolse ogni profeta?", ["Pastore", "Falegname", "Fabbro", "Mercante"], "«Allah non ha inviato alcun profeta che non abbia pascolato pecore», e il Profeta ﷺ le pascolava per gli abitanti della Mecca."),
"prophets_131": ("Secondo un hadith in Muslim, quale profeta lavorò come falegname?", ["Zakariyya", "Nuh", "Idris", "Yusuf"], "Il Profeta ﷺ disse: «Zakariyya era un falegname.»"),
"prophets_132": ("Di quale profeta il Profeta ﷺ disse di essere «il più vicino tra le persone», in questo mondo e nell'Altro?", ["Isa figlio di Maryam", "Musa", "Ibrahim", "Nuh"], "«Io sono il più vicino di tutti a Isa figlio di Maryam in questo mondo e nell'Aldilà; i profeti sono fratelli.»"),
"prophets_133": ("Quante sure del Corano portano il nome di un profeta?", ["Sei", "Due", "Dodici", "Venticinque"], "Yunus (10), Hud (11), Yusuf (12), Ibrahim (14), Muhammad (47) e Nuh (71)."),
"prophets_134": ("Con quali tre parole il Corano descrive Ibrahim nel versetto 11:75?", ["Mite, dal cuore tenero, sempre pronto a tornare ad Allah", "Ricco, potente, dotto", "Forte, veloce, coraggioso", "Re, giudice, guerriero"], "«In verità, Ibrahim era mite, compassionevole e sempre pronto a tornare ad Allah.»"),
"prophets_135": ("Per che cosa Shu'ayb rimproverò il suo popolo, oltre all'idolatria?", ["Frodare nei pesi e nelle misure", "Non pregare", "Viaggiare di notte", "Mangiare pesce"], "«Date misura e peso pieni, e non private la gente di ciò che le spetta.»"),
"prophets_136": ("Che cosa colpì il popolo di Shu'ayb dopo che respinse il suo messaggio?", ["Un terremoto", "Un diluvio", "Una pioggia di fuoco", "Uno stormo di uccelli"], "«Allora il terremoto li colpì, e giacquero nelle loro case, cadaveri riversi.»"),
"prophets_137": ("Quale notizia diedero gli angeli a Ibrahim dopo aver calmato il suo timore?", ["Che erano inviati al popolo di Lut", "Che stava arrivando un diluvio", "Che la Ka'ba sarebbe stata distrutta", "Che il Faraone sarebbe annegato"], "«Non temere: siamo stati inviati al popolo di Lut.»"),
"prophets_138": ("Che cosa chiese Ibrahim per sé e per i suoi discendenti nel versetto 14:40?", ["Di essere assidui nella preghiera", "Di essere re", "Di essere ricchi", "Di vivere a lungo"], "«Signore mio, fa' che io sia assiduo nella preghiera, e così la mia discendenza.»"),
"prophets_139": ("Alla fine della storia di Yusuf, chi fece salire sul trono prima che tutti si prostrassero davanti a lui?", ["I suoi genitori", "Il re", "I suoi fratelli", "Suo figlio"], "«Fece salire i suoi genitori sul trono, e caddero davanti a lui in prostrazione»: il sogno dell'infanzia si avverò."),
"prophets_140": ("Perché i fratelli di Yusuf volevano sbarazzarsi di lui?", ["Per gelosia: il padre lo amava di più", "Aveva rubato", "Rifiutava di lavorare", "Era malato"], "«Yusuf e suo fratello sono più cari a nostro padre di noi… Uccidete Yusuf o abbandonatelo in qualche terra.»"),
"prophets_141": ("Che cosa portarono i fratelli di Yusuf al padre per fargli credere che un lupo lo avesse divorato?", ["La sua camicia macchiata di sangue falso", "I suoi sandali", "Il suo bastone", "Un dente di lupo"], "«Portarono la sua camicia con sopra sangue falso»; Ya'qub rispose: «La pazienza è la cosa migliore.»"),
"prophets_142": ("Che cosa promise Allah alla madre di Musa ispirandola a metterlo nel fiume?", ["Di restituirglielo e farne un messaggero", "Di darle un altro figlio", "Di farla regina", "Di mandare la pioggia"], "«Non temere e non affliggerti: te lo restituiremo e ne faremo uno dei messaggeri.»"),
"prophets_143": ("Con che cosa Musa colpì il mare perché si aprisse?", ["Con il suo bastone", "Con la mano", "Con una pietra", "Con la spada"], "«Colpisci il mare con il tuo bastone»: si aprì, e ogni lato era come un'enorme montagna."),
"prophets_144": ("Qual è la prima cosa che Allah disse a Musa rivolgendosi a lui?", ["«Io sono Allah, non c'è dio all'infuori di Me: adoraMi e compi la preghiera»", "«Va' a pescare»", "«Costruisci un'arca»", "«Torna dal Faraone»"], "«In verità, Io sono Allah; non c'è divinità all'infuori di Me, dunque adoraMi e compi la preghiera per ricordarMi.»"),
"prophets_145": ("Come Allah disse a Musa e Harun di parlare al Faraone?", ["Con parole gentili", "Con collera", "Gridando", "In silenzio"], "«Andate dal Faraone… e parlategli con parole gentili; forse rifletterà o temerà.»"),
"prophets_146": ("Che cosa disse Musa al suo giovane servo all'inizio del viaggio verso la confluenza dei due mari?", ["Che non si sarebbe fermato finché non avesse raggiunto la confluenza dei due mari", "Che voleva tornare a casa", "Che aveva paura", "Che cercava dell'oro"], "«Non desisterò finché non avrò raggiunto la confluenza dei due mari, dovessi camminare per anni.»"),
"prophets_147": ("Quale di queste cose fece il servo sapiente davanti a Musa, che allora non capì?", ["Fece un buco in una barca", "Costruì un ponte", "Accese un fuoco", "Piantò un albero"], "Forò la barca, poi uccise un ragazzo, poi raddrizzò un muro, e in seguito spiegò a Musa ogni gesto."),
"prophets_148": ("Quali furono le prime parole di Isa, ancora nella culla?", ["«Io sono il servo di Allah; Egli mi ha dato la Scrittura e mi ha fatto profeta»", "«Io sono il figlio di Dio»", "«Io sono un re»", "«Ho fame»"], "«Disse: in verità, io sono il servo di Allah. Egli mi ha dato la Scrittura e mi ha fatto profeta.»"),
"prophets_149": ("Che cosa dissero Adam e sua moglie ad Allah dopo aver mangiato dall'albero?", ["«Signore nostro, abbiamo fatto torto a noi stessi; se non ci perdoni, saremo perduti»", "«Non è stata colpa nostra»", "«È stata colpa dell'albero»", "Non dissero nulla"], "«Signore nostro, abbiamo fatto torto a noi stessi, e se non ci perdoni e non hai misericordia di noi, saremo certamente tra i perdenti.»"),
"prophets_150": ("Quale missione Allah affidò a Nuh verso il suo popolo, nel primo versetto della sura Nuh?", ["Ammonirli prima che giungesse loro un castigo doloroso", "Costruire una città", "Insegnare loro a pescare", "Farne dei re"], "«Inviammo Nuh al suo popolo: ammonisci il tuo popolo prima che giunga loro un castigo doloroso.»"),
}
